{
  "technical_and_design_decisions": [
    "Target runtime is Spring XD compatible with Spring Framework 6.0+ and Java 17+, built on Spring Boot 3.x for all modules",
    "For the stream destroy --clean feature, use RabbitAdmin.getQueueProperties() to validate active consumers before resource deletion, with a fallback to direct RabbitMQ Management REST API calls until Spring AMQP's RabbitManagementTemplate is generally available, controlled by a feature flag",
    "For security configuration, leverage Spring Security 6 out-of-the-box features with property-based credential configuration for all components; DSL shell uses Spring Shell's built-in Spring Security integration, and Admin UI shares the same Spring Security context as REST endpoints",
    "For error channel notifications, expose the existing Spring Integration module error channel as a first-class tapable stream source, with enriched metadata (stream name, module name, exception details, timestamp) added to each error message",
    "For status change updates, use the existing Spring XD message bus to propagate deployment/status events between containers and the admin server, with client-side polling as a fallback for UI clients to ensure no updates are missed",
    "For the SFTP source module, use the Spring Integration SFTP inbound channel adapter, with Apache MINA SSHD embedded server for integration testing",
    "For the Elasticsearch sink module, use Spring Data Elasticsearch 8.x with support for auto-index creation, configurable document mapping, and bulk indexing for performance",
    "For the MVC-aware HTTP module, use embedded Tomcat 10.x (compatible with Spring Boot 3.x) with Spring MVC, leveraging Spring Boot auto-configuration for content-type negotiation and full HTTP header mapping to message headers",
    "All ${xd.*} property placeholders are resolved via Spring's existing PropertySourcesPlaceholderConfigurer, so documentation will cover all placeholders exposed by runtime, stream, job, and container components"
  ],
  "assumptions": [
    "Existing Spring XD core components (CLI, Admin UI, message bus, module lifecycle management, base REST API) are already implemented and can be extended without full reimplementation",
    "External dependencies (RabbitMQ with management plugin enabled, Elasticsearch 8.x instances, standard SFTP servers) are compatible with the versions of Spring AMQP, Spring Data Elasticsearch, and Spring Integration SFTP used in the implementation",
    "Users have administrative access to configure security credentials via standard Spring Boot property files for all Spring XD components",
    "The existing Spring XD message bus is capable of propagating deployment and status change events between containers and the admin server without major modifications",
    "Users are responsible for ensuring no critical data exists in queues/topics before using the stream destroy --clean flag, as the feature will delete all associated resources",
    "Spring AMQP's RabbitManagementTemplate will be released in a future version, and the current direct REST API implementation can be migrated to it with minimal changes via the existing feature flag",
    "Existing Spring XD module infrastructure supports the new module types (HTTP, SFTP, Elasticsearch) without core modifications to the module deployment and configuration framework",
    "The existing Spring XD module runtime already captures exceptions and routes them to a default error channel, so only exposure as a stream source is required for the error channel feature"
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Design stream destroy --clean CLI flag and API parameter",
      "activity_description": "Define the --clean CLI flag for the stream destroy command, corresponding API endpoint parameter, and expected behavior for optional resource cleanup",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A2",
      "activity_name": "Implement queue/topic consumer and data validation logic",
      "activity_description": "Integrate with RabbitAdmin.getQueueProperties() to check for active consumers, validate that queues/topics have no pending data, and confirm cleanup is safe to proceed",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A3",
      "activity_name": "Implement RabbitMQ resource cleanup logic",
      "activity_description": "Implement ordered deletion of stream-associated bindings, queues, and fanout exchanges, with checks to avoid deleting shared exchanges used by other streams",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A4",
      "activity_name": "Implement RabbitMQ Management REST API fallback",
      "activity_description": "Add direct REST client for RabbitMQ Management API as a fallback for resource cleanup, with a feature flag to enable migration to RabbitManagementTemplate when it is released",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A5",
      "activity_name": "Add tests for stream destroy clean functionality",
      "activity_description": "Write unit and integration tests covering edge cases: active consumers, shared exchanges, queues with pending data, and cleanup failure scenarios",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A6",
      "activity_name": "Design error channel stream tap interface",
      "activity_description": "Define the structure of the exposed error channel stream, message format (including stream/module metadata, exception details, timestamp), and tap configuration options",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A7",
      "activity_name": "Implement error channel routing and message enrichment",
      "activity_description": "Integrate with existing module error handling to route exceptions to the exposed error channel stream, and enrich messages with stream name, module name, and full exception context",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A8",
      "activity_name": "Add tests for error channel functionality",
      "activity_description": "Write unit and integration tests to validate exception propagation, message content accuracy, and metadata enrichment for error messages",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A9",
      "activity_name": "Research Spring Security 6 and Spring Boot 3 OOTB security features",
      "activity_description": "Research and document available out-of-the-box security features (authentication providers, authorization rules, property-based config) compatible with Spring XD's architecture",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A10",
      "activity_name": "Design Spring XD security configuration approach",
      "activity_description": "Design the end-to-end security configuration model: property-based credential setup, integration with DSL shell, and Admin UI security alignment with REST endpoints",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A11",
      "activity_name": "Implement Spring Security configuration for REST endpoints",
      "activity_description": "Configure Spring Security 6 for all Spring XD REST endpoints, including authentication, authorization rules, and integration with existing user/property sources",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A12",
      "activity_name": "Implement security integration for DSL shell",
      "activity_description": "Integrate Spring Shell with the existing Spring Security context to enforce authentication and authorization for CLI access, aligned with REST endpoint security rules",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A13",
      "activity_name": "Implement security integration for Admin UI",
      "activity_description": "Integrate the Spring XD Admin UI with the shared Spring Security context, including session management and access control consistent with REST/CLI security",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A14",
      "activity_name": "Add tests for security functionality",
      "activity_description": "Write unit and integration tests covering endpoint access control, CLI access control, UI access control, and unauthorized access rejection scenarios",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A15",
      "activity_name": "Audit existing ${xd.*} property placeholders",
      "activity_description": "Search the Spring XD codebase, configuration files, and existing documentation to catalog all available ${xd.[stream|job|container].*} placeholders and their scope",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A16",
      "activity_name": "Update documentation for ${xd.*} placeholders",
      "activity_description": "Update official Spring XD documentation with the full list of available placeholders, usage examples, and scope (stream, job, container level)",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A17",
      "activity_name": "Design MVC-aware HTTP module architecture",
      "activity_description": "Design the new HTTP module structure leveraging Spring MVC and embedded Tomcat, including content-type negotiation, full HTTP header mapping, and compatibility with existing Spring XD module lifecycle",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A18",
      "activity_name": "Implement MVC-aware HTTP source module",
      "activity_description": "Implement the HTTP source module with embedded Tomcat 10.x, Spring MVC integration, content-type based request handling, and full mapping of HTTP headers to message headers",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A19",
      "activity_name": "Implement Spring Security integration for HTTP module",
      "activity_description": "Integrate the HTTP module with the global Spring XD security configuration to secure HTTP endpoints, leveraging existing security rules and credential setup",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A20",
      "activity_name": "Add tests for HTTP module functionality",
      "activity_description": "Write unit and integration tests covering content-type handling, header mapping, security enforcement, and module lifecycle (deploy/undeploy/start/stop) for the HTTP module",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A21",
      "activity_name": "Design event propagation mechanism for status changes",
      "activity_description": "Design the event payload structure and propagation flow using the existing Spring XD message bus to send deployment/status change events between containers and the admin server",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A22",
      "activity_name": "Implement server-side event publishing for lifecycle events",
      "activity_description": "Add event publishing logic to all stream/job/module lifecycle points (deploy, undeploy, start, stop, failure) and integrate with the message bus for event distribution",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A23",
      "activity_name": "Implement client-side polling for UI status updates",
      "activity_description": "Implement polling logic in the Admin UI client to fetch stream/job status changes as a fallback for missed server-side events, with efficient delta fetching to reduce load",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A24",
      "activity_name": "Add tests for event propagation and polling",
      "activity_description": "Write unit and integration tests to validate event delivery, payload correctness, polling accuracy, and fallback behavior when events are missed",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A25",
      "activity_name": "Design SFTP source module architecture",
      "activity_description": "Design the SFTP source module configuration options (connection settings, polling interval, file filters, error handling) using the Spring Integration SFTP inbound channel adapter",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A26",
      "activity_name": "Implement SFTP source module",
      "activity_description": "Implement the SFTP source module with support for connection configuration, file polling, file-to-message conversion, and error handling (retries, dead letter queue)",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A27",
      "activity_name": "Implement SFTP module test infrastructure",
      "activity_description": "Set up an embedded Apache MINA SSHD SFTP server for integration testing, and create test file scenarios for valid and invalid file transfers",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A28",
      "activity_name": "Add tests for SFTP module functionality",
      "activity_description": "Write unit and integration tests covering file polling, transfer, error handling (connection failures, invalid credentials), and file filter functionality",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A29",
      "activity_name": "Design Elasticsearch sink module architecture",
      "activity_description": "Design the Elasticsearch sink module configuration options (connection settings, index name, document mapping, bulk size) using Spring Data Elasticsearch 8.x",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A30",
      "activity_name": "Implement Elasticsearch sink module",
      "activity_description": "Implement the Elasticsearch sink module with support for connection configuration, message-to-document conversion, auto-index creation, bulk indexing, and error handling",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A31",
      "activity_name": "Add tests for Elasticsearch sink functionality",
      "activity_description": "Write unit and integration tests covering document indexing, mapping validation, bulk operations, error handling (Elasticsearch unavailability, invalid documents), and index auto-creation",
      "most_likely_effort": 12
    }
  ],
  "reported_total": {
    "most_likely_effort": 310
  }
}

